INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(439500, 0, 4395, 0, 0, 13, 'Dalaran', 'Dalaran, the city of the Kirin Tor, hangs in the sky above Crystalsong Forest. For years it stood behind a violet dome on the shores of Lordamere Lake, where the mages rebuilt what the Burning Legion had torn down in the Third War. Faced with the rising threats of the blue dragonflight and the Scourge, they have now lifted the whole city and carried it to the heart of Northrend. Rhonin leads the Kirin Tor from the Violet Citadel, and the city''s mages fight their own war against Malygos and his flight. Dalaran''s streets are open to the Alliance and the Horde alike, though each keeps a guarded quarter of its own: the Silver Enclave of Vereesa Windrunner''s high elves, and Sunreaver''s Sanctuary, held by the blood elves of Archmage Aethas Sunreaver. Beneath the streets, the sewers of the Underbelly shelter rogues, gamblers and duelists. The citizens say the Lich King''s grasp has not reached their city yet.', 'Faction.dbc 1090 Kirin Tor description (faced with the blue dragonflight and the Scourge, transported their city to the heart of Northrend); quests 12791/12794/12796 description (no longer under its dome on the shores of Lordamere Lake; floats above Crystalsong Forest); alterac.json (rebuilt behind the dome after the Third War); creature_template 16128 (Rhonin, Leader of the Kirin Tor); Faction.dbc 1094 and 1124 (Silver Covenant under Vereesa; Sunreavers of Aethas watch Sunreaver''s Sanctuary); npc_text 13972, 13973 (Alliance and Horde quarters); warcraft.wiki.gg/wiki/The_Underbelly (sewers, rogues'' Black Market, arena and dueling); creature_text 32451 (the Lich King''s grasp has not reached Dalaran yet); warcraft.wiki.gg/wiki/Rhonin (leads the war against Malygos from the Violet Citadel)'),
(439501, 1, 4395, 1, 0, 13, 'The Violet Citadel', 'The Violet Citadel is the inner fortress of the Kirin Tor and the seat of their leader. In its great hall Rhonin keeps counsel with his wife Vereesa Windrunner of the Silver Covenant, Archmage Aethas Sunreaver of the Sunreavers and Archmage Modera, while Archmage Alvareaux serves as quartermaster to those who have earned the order''s favor. The citadel''s shelves keep the city''s memory. The journal of Archmage Antonidas records his study of the plague of the north and his choice of Jaina Proudmoore to seek out its source, and a ledger of the Kirin Tor''s losses in the Third War notes that Bethor Iceshard has risen among the Forsaken and that Thule Ravenclaw seems to have sided with the Scourge.', 'warcraft.wiki.gg/wiki/Dalaran_(Northrend) (Violet Citadel the inner fortress); creature spawns 16128, 30115, 30116, 30117 together at the citadel (z 662); creature_template subnames; creature 32287 Archmage Alvareaux, Kirin Tor Quartermaster (z 680); gameobject 192880 Journal of Archmage Antonidas (page 3432) beside Rhonin; gameobject 192887 Losses of the Third War (page 3479), z 680'),
(439502, 1, 4395, 2, 0, 13, 'Krasus'' Landing', 'Krasus'' Landing, at the eastern edge of Dalaran, is where riders on the wing come and go, and it bears the name of Krasus, long a friend of the Kirin Tor. Aludane Whitecloud keeps the city''s flight paths, and the high elf Hira Snowdawn teaches riders to fly in the cold northern skies, though between lessons she yawns and looks about, bored, from the back of her dragonhawk Cloudwing. Archmage Pentarus, who helped fund an expedition to Sholazar Basin, keeps his post here. Officers of the gunships Skybreaker and Orgrim''s Hammer wait on the landing with Alliance marines and Kor''kron reavers, ready to carry volunteers to the war above Icecrown.', 'npc_text 14004, 14009 (flight master and cold weather flying trainer at Krasus'' Landing); warcraft.wiki.gg/wiki/Krasus''_Landing (named for Krasus); quest 14444 description (Krasus long a friend to the Kirin Tor); creature_text 31238 (Hira and Cloudwing; yawns, looks around bored); npc_text 13998 (Hira Snowdawn, high elf, on her dragonhawk); sholazar.json and quest 12521 (Pentarus helped fund the expedition; quest not used); npc_text 13901, 13902 (Skybreaker and Orgrim''s Hammer officers); creature spawns 30352 Skybreaker Marine, 30755 Kor''kron Reaver beside 31081 and 31085'),
(439503, 1, 4395, 3, 0, 13, 'Runeweaver Square', 'Runeweaver Square is a park at the very heart of Dalaran, set between the city''s two rival quarters. The life of the city flows around it. The Legerdemain Lounge, the most popular inn in Dalaran, opens onto the square, where Amisi Azuregaze hopes every guest enjoys the stay. Not far off, Jepetto Joybuzz fills the Wonderworks with toys for young and old while clockwork robots and a little toy plane circle the shop. In the portal chamber at the square''s eastern corner, the Violet Gate, Archmage Celindra teaches portal magic, and a crystal behind her carries travelers down to the Violet Stand in Crystalsong Forest.', 'npc_text 13967 (park at the very heart of Dalaran); warcraft.wiki.gg/wiki/Runeweaver_Square (between the Silver Enclave and Sunreaver''s Sanctuary; the Violet Gate nested under it); npc_text 14002 (Legerdemain Lounge the most popular inn); quest 13101 (Legerdemain Lounge found in Runeweaver Square); npc_text 14162 (Amisi Azuregaze); npc_text 14082 (Wonderworks, toys for young and old); cosmetic clockwork robot and toy plane spawns 29783-29812 at the shop; quest 13102 (portal chamber in the eastern corner of Runeweaver Square); npc_text 13455 (Celindra; crystal to the ruins below); WMOAreaTable groups 24939-24943 The Violet Gate; spawns: Silver Enclave guards near 5730,720, Sunreaver guards near 5900,540, Amisi 5848,635, Celindra 5808,585, Jepetto 5814,681'),
(439504, 1, 4395, 4, 0, 13, 'Antonidas Memorial', 'The Antonidas Memorial is a park in northern Dalaran where a statue of Archmage Antonidas, Grand Magus of the Kirin Tor, rises above the lawns. Its plaque was dedicated by his apprentice, Lady Jaina Proudmoore: the city stands once more, she wrote, a testament to the will of its greatest son, and his sacrifices were not in vain. Volumes left around the city tell how he joined the Kirin Tor as a boy, how he warned that the plague of the north was magical and urged a quarantine that King Terenas refused, and how he stood before Arthas''s army at Dalaran, until the prince broke his wards and slew him.', 'npc_text 13968 (memorial park in northern Dalaran); gameobject 193942 Archmage Antonidas plaque, page_text 3542 (Grand Magus; city stands again, testament to its greatest son; sacrifices not in vain; Jaina Proudmoore); warcraft.wiki.gg/wiki/Antonidas_Memorial (statue with staff and orb); gameobjects 192870-192872 The Archmage Antonidas parts I-III (pages 3403, 3409, 3414), placed around the city'),
(439505, 1, 4395, 5, 0, 13, 'The Eventide', 'The Eventide is a square in southern Dalaran, gathered around an enchanted fountain that the city''s anglers love. Marcia Chase teaches fishing at its edge, and the Dalaran Merchants'' Bank opens onto the square. Over the years a great many coins have been tossed into the fountain, and patient hooks bring them up again, each still carrying its owner''s wish: Antonidas asking for the strength to accept what he could not change, Jaina Proudmoore begging Arthas to come back to her, Krasus swearing to free his kin still suffering in Grim Batol, and Khadgar hoping that Turalyon and Alleria are well, wherever they may be.', 'npc_text 13966, 13987 (square in southern Dalaran; enchanted fountain popular for fishing; learn to fish there); npc_text 14006 (Dalaran Merchants'' Bank off the Eventide); fishing_loot_template 4568 (reference 11025, the coins); item_template descriptions 43678 (Antonidas), 43628 (Jaina), 43712 (Krasus), 43683 (Khadgar); creature 28742 Marcia Chase beside the fountain spell focus 193387'),
(439506, 1, 4395, 6, 0, 13, 'Magus Commerce Exchange', 'The Magus Commerce Exchange is Dalaran''s trade district, where nearly every master craftsman in the city keeps shop. A door shaped like a potion marks the Agronomical Apothecary, with its greenhouse of herbalists. The smiths work at a massive enchanted anvil beneath stained glass windows shaped like axes and shields, Cartier and Co. sells fine jewelry, Talismanic Textiles serves the city''s tailors and Like Clockwork its engineers, and the clinic First to Your Aid tends the injured. In the Scribes'' Sacellum the ancient tomes of the Lexicon of Power lie open to inscribers.', 'npc_text 13980 (Magus Commerce Exchange holds most profession trainers); npc_text 13995, 13986 (potion-shaped door; greenhouse); npc_text 13994 (smithy, enchanted anvil, axe and shield windows); npc_text 13984, 13981, 13989, 13988, 13985 (Cartier and Co., Talismanic Textiles, Like Clockwork, First to Your Aid, Scribes'' Sacellum); npc_text 14174 and gameobject 193981 Lexicon of Power'),
(439507, 1, 4395, 7, 1, 13, 'The Silver Enclave', 'The Silver Enclave is the Alliance quarter of Dalaran, kept by the high elves of the Silver Covenant, and its guardian mages turn back any member of the Horde who tries to enter, teleporting the trespasser out of the quarter. Within lie portals to the Alliance capitals and the inn A Hero''s Welcome, with its beer garden and one of the city''s finest cooks in the kitchen. Arcanist Braedin opens a portal for those bound to the battle for Wintergrasp, and Grand Marauder Sai, who remembers the Horde chiefly for the sorrow and sacrifice it has cost him, has never let go of his fury.', 'Faction.dbc 1094 (Silver Covenant); zone_dalaran.cpp npc_mageguard_dalaran (Silver Covenant Guardian Mages cast Trespasser! 54028 on the Horde in area 4740 or the quarter''s WMO groups); npc_text 13973, 13992 (portals; A Hero''s Welcome with beer garden and cooking trainer); creature_text 32169 (Braedin''s Wintergrasp portal); npc_text 13574 (Grand Marauder Sai); quest 14457 (Alliance only, turned in to Arcanist Tybalin in the Silver Enclave)'),
(439508, 1, 4395, 8, 2, 13, 'Sunreaver''s Sanctuary', 'Sunreaver''s Sanctuary is the Horde quarter of Dalaran, a ward kept by the followers of Archmage Aethas Sunreaver, and its guardian mages teleport away any member of the Alliance who strays inside. The Horde was long barred from Dalaran and was accepted into the city only through Aethas''s efforts. Portals here lead to the Horde capitals, and the inn called the Filthy Animal is a rough place, where Uda the Beast urges guests to eat and rest before their next battle, but warns that brawlers end up feeding the wolves. High Arcanist Savor warns that it is unwise to challenge a master of the arcane, and Magister Surdiel calls fighters to the battle for Wintergrasp.', 'Faction.dbc 1124 (Horde traditionally barred from Dalaran, accepted through Aethas''s efforts; followers watch over Sunreaver''s Sanctuary); zone_dalaran.cpp npc_mageguard_dalaran (Sunreaver Guardian Mages cast Trespasser! 54029 on the Alliance in area 4616 or the quarter''s WMO groups); npc_text 13972, 13993 (portals; the Filthy Animal a rough place); npc_text 14077 (Uda the Beast); npc_text 13573 (High Arcanist Savor); creature_text 32170 (Magister Surdiel, Wintergrasp); quest 24557 (Horde only, turned in to Magister Hathorel in Sunreaver''s Sanctuary)'),
(439509, 1, 4395, 9, 0, 13, 'The Underbelly', 'The Underbelly, the sewer beneath Dalaran, is the city''s slum and the haunt of its disreputable types. The Cantrips and Crows Tavern serves them, its innkeeper warning guests to watch their backs, since the barmaid hates scrubbing blood off the floor. Rogues run the Black Market nearby, Pazik ''The Pick'' Prylock replaces lost keys, and Scout Nisstina, the Three Fingered Bandit, preaches the sweetness of stolen goods. The Steamwheedle Cartel runs an arena circuit in the central sewers, with dueling rings at the Circle of Wills, and Adamman the Trader, ruined when the Cartel caught him rigging fights, now wears rags. A pipe drops out of the bottom of the city, safe only for those who can fly.', 'warcraft.wiki.gg/wiki/The_Underbelly (Dalaran''s slum; Black Market run by rogues; Circle of Wills; exit pipe); npc_text 14251 (locksmith; disreputable types in the sewers); npc_text 14163 (Ajay Green, Cantrips and Crows, Narisa and the blood); npc_text 13572 and gossip options (Pazik''s keys); npc_text 14090 (Scout Nisstina); npc_text 14023 (Steamwheedle Cartel arena circuit, dueling at the Circle of Wills); npc_text 13707 (Adamman: caught rigging fights by the Cartel; rags and a bad liver); npc_text 14026 (tunnel out of the bottom of Dalaran; be sure you can fly)'),
(439510, 1, 4395, 10, 0, 13, 'The Violet Hold', 'The Violet Hold is Dalaran''s prison, where the Kirin Tor keep the enemies of their order behind lock and ward. Warden Alturas oversees it, and the Violet Hold''s guards keep watch at its gates. Whatever goes on inside, not all of it stays there: anglers who fish the water around the prison pull up rusted prison keys and bloodied shanks, and the shanks suggest that someone inside does a brisk trade.', 'npc_text 13970 (the Violet Hold, prison for the enemies of the Kirin Tor); creature 31080 Warden Alturas and 30659 Violet Hold Guard outside the hold; fishing_loot_template 4567 (reference 11024: Rusty Prison Key 43650 and Bloodied Prison Shank 43659 at 1 percent each); item_template 43659 description (profits were high this year)'),
(439520, 2, 4395, 0, 0, 13, 'Rhonin', 'Rhonin is the leader of the Kirin Tor, a human archmage who welcomes visitors to the home of his order from the great hall of the Violet Citadel. Years ago, as a young mage sent on a desperate mission into Khaz Modan, he helped free the Dragonqueen Alexstrasza from her captivity in Grim Batol, and on that journey he met the high elf ranger Vereesa Windrunner, who became his wife and the mother of his twin sons. The Kirin Tor turned to him to lead them in hard times, and under him they have carried Dalaran to Northrend to face the blue dragonflight and the Scourge, with Vereesa, Archmage Aethas Sunreaver and Archmage Modera at his side.', 'creature_template 16128 (Rhonin, Leader of the Kirin Tor); npc_text 14161 (welcome to the home of the Kirin Tor); warcraft.wiki.gg/wiki/Rhonin (Day of the Dragon: mission into Khaz Modan, Alexstrasza freed at Grim Batol, meets Vereesa; marriage and twin sons; Night of the Dragon: asked to lead the Kirin Tor; Wrath: leads from the Violet Citadel with Vereesa, Modera and Aethas); Faction.dbc 1090 (city moved to face the blue dragonflight and the Scourge)'),
(439521, 2, 4395, 1, 0, 13, 'Vereesa Windrunner', 'Vereesa Windrunner is the Ranger General of the Silver Covenant and the youngest of the Windrunner sisters, after Alleria and Sylvanas. Once a ranger of Quel''Thalas, she was sent to guide a young human mage named Rhonin and fought beside him at Grim Batol; she is now his wife and the mother of his twin sons. When blood elves sought a place among the Kirin Tor, she gathered the high elves who would not accept them into the Silver Covenant, a militant order that has joined the Alliance forces in Northrend. In the Violet Citadel she stands at her husband''s side.', 'creature_template 30115 (Ranger General of the Silver Covenant); Faction.dbc 1094 (militant core of high elves rejecting blood elves in the Kirin Tor, united under Vereesa, joined the Alliance forces in Northrend); warcraft.wiki.gg/wiki/Vereesa_Windrunner (youngest sister of Alleria and Sylvanas; Farstrider; escorted Rhonin, Grim Batol; married Rhonin, twin sons; founded the Silver Covenant); creature spawn 30115 beside Rhonin in the Violet Citadel; warcraft.wiki.gg/wiki/Vereesa_Windrunner (twin sons Giramar and Galadin named in the War of the Ancients trilogy, before Wrath)'),
(439522, 2, 4395, 2, 0, 13, 'Aethas Sunreaver', 'Archmage Aethas Sunreaver is a blood elf of the Kirin Tor and the champion of his people in Dalaran. The Horde had long been barred from the city, and it was through his efforts that it was accepted at all; his followers have taken up his name as the Sunreavers and keep the ward of Sunreaver''s Sanctuary. Not everyone welcomes them, for the high elves of the Silver Covenant reject the admission of blood elves into the Kirin Tor outright. Aethas stands beside Rhonin in the Violet Citadel, and an image of him carries the Kirin Tor''s counsel to the Horde at Agmar''s Hammer.', 'creature_template 30116 (Archmage Aethas Sunreaver, Kirin Tor); Faction.dbc 1124 (Horde accepted through his efforts; his followers took up his name and watch over Sunreaver''s Sanctuary); Faction.dbc 1094 (Silver Covenant rejects blood elves in the Kirin Tor); dragonblight.json (image of Aethas at Agmar''s Hammer); creature spawn 30116 beside Rhonin in the Violet Citadel'),
(439523, 2, 4395, 3, 0, 14, 'Marcia Chase', 'Marcia Chase is Dalaran''s grand master of fishing, who teaches the craft and sells tackle beside the fountain in the Eventide. Any Northrend angler worth their salt should know the waters of this land, she holds, and she sends the bold far afield after strange catches: the bloodtooth of the Borean Tundra, best caught by fishing in a pool of blood, the terrorfish of Wintergrasp, as lethal as it is delicious, and the jewelry lost in the city''s own sewers.', 'creature_template 28742 (Grand Master Fishing Trainer and Supplies); spawn beside the Eventide fountain; quests 13833 (bloodtooth, blood pools, Borean Tundra), 13834 (terrorfish, Wintergrasp, lethal and delicious, her stories), 13832 (sewer jewelry) descriptions; quest 13830 description (any Northrend angler worth their salt) and request text (proud of her pun)'),
(439540, 3, 4395, 0, 0, 13, 'The Kirin Tor''s Invitation', 'Once a traveler in Northrend has proven ready, the Kirin Tor''s envoys in its towns and camps pass on an invitation: Dalaran no longer sits beneath its dome on the shores of Lordamere Lake, but floats above Crystalsong Forest. The envoy offers to send the traveler there by a spell of teleportation and hands over a Kirin Tor signet as proof of the meeting, to be given to Archmage Celindra at the Violet Gate. Celindra welcomes the newcomer to Dalaran and promises that the ring will be returned.', 'quests 12791, 12794, 12796 description and reward text; creature_queststarter for 12791/12794/12796 (Kirin Tor envoys and archmage images across Northrend); npc_text 13455 (Celindra)'),
(439541, 3, 4395, 1, 0, 16, 'The Wyrmrest Tome', 'A battered hilt carried out of Icecrown Citadel has set Dalaran''s two elven orders, the Silver Covenant and the Sunreavers, racing to learn what sword it came from. Each keeps people at Quel''Delar''s Rest, south of the Argent Tournament grounds, and whichever order sees the hilt first judges it part of a powerful, ancient weapon and sends the one who found it to Krasus at Wyrmrest Temple, long a friend to the quel''dorei and the Kirin Tor. Krasus has a book that might name the blade, but he has already lent it to the other order. Back in Dalaran, that champion is set to win the tome before the rivals can carry it to Icecrown.', 'quests 14443 and 24554 description and reward text (hilt recovered in the citadel; representatives at Quel''Delar''s Rest, south of the tournament grounds); quests 14444 and 24555 description and reward text (powerful, ancient weapon; Krasus long a friend to the quel''dorei and the Kirin Tor; the book Krasus lent the other order); quests 14457 and 24557 description (offered at that turn-in: do not let them get it back to Icecrown first); creature 36624 Caladis Brightspear and 36642 Myralion Sunblaze at Quel''Delar''s Rest; warcraft.wiki.gg/wiki/Quel''Delar; www.wowhead.com/wotlk/quest=20438 (A Suitable Disguise, in the Alliance chain 14443, 14444, 14457, 20438, 20439, 24454)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(439500, 1, 16, 255, 'With a gap found in the defenses of Icecrown Citadel, two envoys now look for fighters in the city''s streets to send north: Apprentice Nelphi of the Kirin Tor, who speaks for Lady Jaina Proudmoore, and Dark Ranger Vorel, who answers to Lady Sylvanas Windrunner. In the Magus Commerce Exchange, Frozo the Renowned has set up as a trader in frozen orbs.', 'quest 24510 description (Nelphi: her patron Jaina found a hole in Icecrown Citadel''s defenses, the Forge of Souls); quest 24506 description (Vorel: my queen Sylvanas); creature_template 37776 (Apprentice Nelphi, Kirin Tor), 37780, 40160 (Frozo the Renowned, Frozen Orb Trader); mod-individual-progression ipp_aware_npcs.sql: 37776, 37780, 40160 npc_ipp_wotlk_icc (state 16)'),
(439501, 1, 0, 255, 'High in one of the citadel''s spires, reached through a portal on the ground floor, lies the Purple Parlor. The butler Alfred Copperworth keeps food and drink for the mages who gather there, and the guests can hardly stop admiring the view, though one laments having left a pouch of light feathers at home, when a slow fall would serve so well from such a height. Higher still is a private room, Archmage Vargoth''s Retreat.', 'gameobjects 194011 Portal to The Purple Parlor (citadel floor, z 681) and 194012 Portal to The Violet Citadel (z 844); spell_target_position 61419; WMOAreaTable groups 25868 The Purple Parlor and 25869 Archmage Vargoth''s Retreat (area 4637); creature 32631 Alfred Copperworth, Butler, at z 844; creature_text 32736, 32739, 32741 (the view up here is amazing; light feathers, Slow Fall); warcraft.wiki.gg/wiki/Purple_Parlor (portal in the ground floor of the citadel); warcraft.wiki.gg/wiki/Archmage_Vargoth''s_Retreat (Vargoth''s room in the Violet Citadel; reached with the book from Higher Learning); spell_target_position 59314 (into the retreat, z 865) and 59316 (out to the great hall); creature 19481 at z 866'),
(439502, 1, 0, 255, 'Archmage Pentarus has his diversions. He likes to watch the occasional game of battle ball, and before a match he wants a picnic basket filled with rhino dogs and wild mustard, picked from the grassy corners of the city, for the trip. All he hopes is that the Dalaran Destroyers might finally win one.', 'quests 13107 and 13116 description (battle ball; picnic basket; wild mustard in the city''s grassy areas) and reward text (Dalaran Destroyers); quest 13107 request text (waiting for my fellow mages)'),
(439502, 2, 15, 255, 'Now that the Argent Crusade has opened its tournament in northern Icecrown, Jean Pierre Poulain, a valiant of the tournament, waits at the landing to pay the passage of anyone who has yet to find the way there. The more who join the melee, he says, the stronger they will all be when they strike against the Lich King.', 'npc_text 14500 (Jean Pierre Poulain gossip); creature 34244 at 5802, 462 beside the flight master; mod-individual-progression ipp_aware_npcs.sql: 34244 npc_ipp_wotlk_totc (state 15)'),
(439506, 1, 0, 255, 'Timothy Jones, the master jeweler of Cartier and Co., fills orders for a wealthy shipping concern that sells Northrend craftwork in Undermine: amulets, brooches, ivory and bone figurines, relics and curios. A shipment always seems to be due, and he is forever short of one stone or another when it must go out.', 'quest 13041 description (shipment to Undermine; short a Chalcedony); quests 12958-12963 descriptions (a wealthy shipping concern; to sell at Undermine); creature 28701 Timothy Jones beside 28721 Tiffany Cartier'),
(439509, 1, 14, 255, 'Marcia Chase claims the sewer waters hold more than giant rats and mutated fish. Their bottom is strewn with jewelry, thrown away by the broken-hearted, dropped by thieves or lost by careless drunks, and an angler who lets the hook drag along the bottom and does not pull too hard may bring up something that could prove valuable once it is cleaned and appraised.', 'quest 13832 description and reward text'),
(439510, 1, 14, 255, 'One inmate proved vicious enough to sever a guard''s arm and throw it into the water outside the prison. Marcia Chase bet her favorite fishing pole that the arm would surface, and once it was fished out it was carried to Olisarra the Kind, whose clinic promised it could be reattached.', 'quest 13836 description and reward text'),
(439521, 1, 16, 255, 'When Quel''Delar had been restored, Vereesa asked to see its bearer in the Violet Citadel, and the sight was more than she could put into words. The day the sword was lost, when Thalorien Dawnseeker and King Anasterian fell, she counts among the darkest she has known. She named the hero who had remade it the blade''s true bearer, and saw its magic already shaping itself to its new wielder.', 'quest 24796 description and reward text'),
(439522, 1, 16, 255, 'When Quel''Delar had been restored, Aethas asked to see its bearer in the Violet Citadel to offer his congratulations in person. To him the sword''s return mirrored the rise of the sin''dorei from defeat and betrayal, and he saw that the blade was already adapting itself to the one who carried it.', 'quests 24800 and 24801 description and reward text'),
(439523, 1, 0, 255, 'Among the pygmy suckerfish of Sholazar''s River''s Heart hides the phantom ghostfish, which grows ever more translucent out of the water until it fades away entirely. Marcia wanted its secret by any means. The answer, once brought to her, was that eating it turns the eater invisible, a strange defense for so clever a fish. She was rather too proud of the pun she made of it, and swore it was not intended.', 'quest 13830 description, request text (proud of her pun) and reward text (pun not intended)'),
(439540, 1, 0, 255, 'Celindra then showed the newcomer the way in and out of the city. A crystal on the platform behind her teleports a traveler down to the Violet Stand in Crystalsong Forest, beneath Dalaran, and another crystal at the stand returns them to the chamber above. She doubts most visitors have the wits for portal magic, but anyone may use the crystals.', 'quest 12790 description and reward text; npc_text 13455 (doubts the visitor''s mental acuity for portal magic; the crystal behind her)'),
(439541, 1, 0, 255, 'A contact in the Underbelly had seen one of the rival order''s agents in the sewers, where its people seldom go. The agent was hunted down and his orders taken from his body: he was to collect the tome from his order''s contact inside its guarded quarter and carry it to Icecrown. That was the chance to seize it, though reaching the contact would not be easy.', 'quests 14457 and 24557 description and reward text'),
(439541, 2, 0, 255, 'Only those who wore the rival order''s tabard could pass its guards, so the champion went to Shandy Glossgleam, who launders clothes for all sorts of people in the city with his water elemental Aquanos on a balcony above the Threads of Fate. A round of frantic washing produced a borrowed tabard, and a simple enchantment made it a disguise. Shandy''s elemental is not always careful: Aethas Sunreaver once found his own trousers in the fountain.', 'quests 20438 and 24556 description and reward text; npc_text 15066 (Shandy and his water elemental); creature_text 36856 (the laundry; group 7, Aethas''s pants in the fountain)'),
(439541, 3, 0, 255, 'Disguised, the champion slipped into the rival quarter and was taken for the courier the agent was meant to be. The contact handed over the book, Ancient Dragonforged Blades, and urged the courier to hurry it to Icecrown before the other side caught on. The book was now to go to Quel''Delar''s Rest after all, but to the champion''s own order, and Shandy was promised his tabard back with a handsome reward for his trouble.', 'quests 20439 and 24451 description (the book''s title; the contact) and reward text (get it to Caladis or Myralion; Shandy to get his tabard back and a reward); creature_text 36669 groups 0-2 and 36670 groups 0-2 (courier; here is the book; get it to Icecrown or to Myralion at once)');
